  {id:47,name:"Le Fil rompu",title:"RUPTURE",category:"Ombre",definition:"Une continuité est rompue. Cette carte parle de séparation ou de perte de lien et demande d’en mesurer les conséquences réelles.",meaning:"Une continuité est rompue. Cette carte parle de séparation ou de perte de lien et demande d’en mesurer les conséquences réelles.",keywords:"rupture, séparation, perte de lien",group:'main',oracle:'reflets',spriteIndex:46},
  {id:48,name:"Les Cendres froides",title:"ÉPUISEMENT",category:"Ombre",definition:"Les ressources sont basses et une phase arrive au bout de ce qu’elle peut donner. Le repos ou la clôture devient prioritaire.",meaning:"Les ressources sont basses et une phase arrive au bout de ce qu’elle peut donner. Le repos ou la clôture devient prioritaire.",keywords:"épuisement, fin de cycle, fatigue",group:'main',oracle:'reflets',spriteIndex:47},
  {id:49,name:"Le Verger sous l’orage",title:"TOURMENTE",category:"Ombre",definition:"Une période de forte tension perturbe l’équilibre. Il vaut mieux sécuriser l’essentiel avant de prendre des décisions irréversibles.",meaning:"Une période de forte tension perturbe l’équilibre. Il vaut mieux sécuriser l’essentiel avant de prendre des décisions irréversibles.",keywords:"crise, tension, instabilité",group:'main',oracle:'reflets',spriteIndex:48},
  {id:50,name:"Le Dernier quai",title:"DÉPART",category:"Ombre",definition:"Une étape demande d’être quittée ou clôturée. Le détachement ouvre une transition, même s’il s’accompagne d’émotion ou d’incertitude.",meaning:"Une étape demande d’être quittée ou clôturée. Le détachement ouvre une transition, même s’il s’accompagne d’émotion ou d’incertitude.",keywords:"départ, détachement, clôture",group:'main',oracle:'reflets',spriteIndex:49}
